import { describe, it, expect } from 'vitest'
import { vars, seed } from 'suite:env'
import { answer } from 'suite:module'

describe('a self-contained api.qa/vitest@1 fixture', () => {
  it('runs the subset with no network at all', () => {
    expect(answer()).toBe(vars.expected)
    expect(typeof seed).toBe('number')
  })
  it('exercises core matchers, .not, and async', async () => {
    expect([1, 2, 3]).toHaveLength(3)
    expect({ a: { b: 1 } }).toMatchObject({ a: { b: 1 } })
    expect(7).not.toBe(8)
    await expect(Promise.resolve('ok')).resolves.toBe('ok')
  })
})
